// wlcb002-read-and-diff (PRO-196)
// Hash-set diff of /miru-data/cc_completion_log.jsonl — same algorithm as
// ccp002 in w-cc-completion-ping.json but with independent state keys so
// both workflows can process the same file without stepping on each other.
//
// State key: lc_pinged_hashes (vs ccp002's cc_completion_pinged_hashes).
// State-wipe / first-run init: seeds silently, no pings on startup.
// Regression alert: fires once when <50% of pinned hashes are present.
const fs = require('fs');
const crypto = require('crypto');
const PATH = '/miru-data/cc_completion_log.jsonl';

function hashRow(line) {
  return crypto.createHash('sha1').update(line.trim()).digest('hex');
}

const staticData = $getWorkflowStaticData('global');
let pinnedHashes = staticData.lc_pinged_hashes;
if (!Array.isArray(pinnedHashes)) pinnedHashes = [];
const pinnedSet = new Set(pinnedHashes);
const regressionAlerted = staticData.lc_regression_alerted === true;

let content = '';
try {
  content = fs.readFileSync(PATH, 'utf8');
} catch (e) {
  if (e && e.code === 'ENOENT') {
    const shouldAlert = pinnedSet.size > 0 && !regressionAlerted;
    if (shouldAlert) staticData.lc_regression_alerted = true;
    return [{ json: { new_rows: [], current_count: 0, regressed: shouldAlert, last_count: pinnedSet.size, _file_missing: true } }];
  }
  throw e;
}

const rows = content.split('\n').filter(line => line.trim().length > 0);
const currentCount = rows.length;

if (pinnedSet.size === 0 && currentCount > 0) {
  staticData.lc_pinged_hashes = rows.map(hashRow);
  staticData.lc_regression_alerted = false;
  return [{ json: { new_rows: [], current_count: currentCount, regressed: false, last_count: 0, _init: true } }];
}

const currentHashSet = new Set(rows.map(hashRow));
let presentCount = 0;
for (const h of pinnedSet) {
  if (currentHashSet.has(h)) presentCount++;
}
const presentRatio = pinnedSet.size > 0 ? presentCount / pinnedSet.size : 1;
const isRegressed = pinnedSet.size > 0 && presentRatio < 0.5;

if (isRegressed) {
  if (regressionAlerted) {
    return [{ json: { new_rows: [], current_count: currentCount, regressed: false, last_count: pinnedSet.size } }];
  }
  staticData.lc_regression_alerted = true;
  return [{ json: { new_rows: [], current_count: currentCount, regressed: true, last_count: pinnedSet.size } }];
}

if (regressionAlerted) {
  staticData.lc_regression_alerted = false;
}

const newRows = rows.filter(line => !pinnedSet.has(hashRow(line)));
staticData.lc_pinged_hashes = [...pinnedHashes, ...newRows.map(hashRow)];

return [{ json: { new_rows: newRows, current_count: currentCount, regressed: false, last_count: pinnedSet.size } }];

// wlcb003a-build-regression-msg (PRO-196)
const data = $input.item.json;
const text = '\u26A0 <b>cc_completion_log.jsonl regressed (bridge)</b>\nrows now=' + (data.current_count != null ? data.current_count : '?') + ', last_seen=' + (data.last_count != null ? data.last_count : '?') + '\n<i>append-only convention violated; manual investigation required</i>';
const telegram_body = {
  chat_id: $env.TELEGRAM_CHAT_ID,
  text,
  parse_mode: 'HTML',
  disable_notification: false
};
return { json: { ...data, telegram_body } };

// wlcb005-parse-row (PRO-196)
// Parse a cc_completion_log.jsonl row. Filter non-PRO tickets.
// Build Linear comment body from completion data, with hash marker for dedup.
const crypto = require('crypto');
function esc(s) { return String(s == null ? '' : s); }

const data = $input.item.json;
const rowStr = data.new_rows;
const rowHash = crypto.createHash('sha1').update(String(rowStr).trim()).digest('hex');

let row;
try { row = JSON.parse(rowStr); }
catch (e) {
  return { json: { _skip: true, _skip_reason: 'invalid JSON: ' + (e && e.message ? e.message : 'unknown'), raw: rowStr, _row_hash: rowHash } };
}

const ticketId = row.ticket_id || '';
if (!/^PRO-/.test(ticketId)) {
  return { json: { _skip: true, _skip_reason: 'non-PRO ticket_id: ' + ticketId, _row_hash: rowHash } };
}

const status = row.status || '';
if (!['CONFIRMED_WORKING', 'INCONCLUSIVE', 'FAILED'].includes(status)) {
  return { json: { _skip: true, _skip_reason: 'unknown status: ' + status, _row_hash: rowHash } };
}

let icon;
if (status === 'CONFIRMED_WORKING') { icon = '\u2705'; }
else if (status === 'INCONCLUSIVE') { icon = '\u26A0\uFE0F'; }
else { icon = '\u274C'; }

const parts = [icon + ' **CC ' + esc(status) + '**', ''];

if (row.summary) parts.push(esc(row.summary), '');
if (row.test_evidence) parts.push('**Test evidence:** ' + esc(row.test_evidence), '');
if (row.branch) parts.push('**Branch:** `' + esc(row.branch) + '`');
if (row.pr_number) parts.push('**PR:** #' + esc(row.pr_number));
if (row.merge_commit_sha && typeof row.merge_commit_sha === 'string') parts.push('**Merge SHA:** `' + esc(row.merge_commit_sha.slice(0, 7)) + '`');
if (row.files_touched && row.files_touched.length) {
  parts.push('', '**Files touched:**');
  for (const f of row.files_touched.slice(0, 20)) parts.push('- `' + esc(f) + '`');
}
if (row.notes) parts.push('', '**Notes:** ' + esc(row.notes));
parts.push('', '<!-- bridge:hash:' + rowHash + ' -->');

const commentBody = parts.join('\n').trim();

return { json: {
  _skip: false,
  ticket_id: ticketId,
  status,
  comment_body: commentBody,
  _row_hash: rowHash
} };

// wlcb008-resolve-ids (PRO-196)
// Extract issue UUID and In Review state ID from the Linear lookup response.
// Sets _linear_skip=true if the issue is not found.
const prior = $('wlcb005-parse-row').item.json;
const resp = $input.item.json;

const data = (resp && resp.data) || {};
const issues = (data.issues && data.issues.nodes) || [];
const states = (data.team && data.team.states && data.team.states.nodes) || [];

const issue = issues[0] || null;
if (!issue) {
  return { json: { ...prior, _linear_skip: true, _linear_err: 'issue not found for ' + prior.ticket_id } };
}

// In Review is a custom state name (not a type) — find by name.
const inReviewState = states.find(s => s.name === 'In Review');

return { json: {
  ...prior,
  _linear_skip: false,
  _issue_id: issue.id,
  _issue_title: issue.title || '',
  _in_review_state_id: inReviewState ? inReviewState.id : null
} };
